  1	/**
  2	 * Queue reading internals for the orchestrator run queue (WP-B extraction).
  3	 *
  4	 * Reads `.run-queue.json`, enriches each raw entry with computed lifecycle
  5	 * state and JSONL progress data, and returns the result as `QueueEntry[]`.
  6	 *
  7	 * This module is read-only with respect to the queue file and all other files.
  8	 *
  9	 * The `isRawQueueEntry` type-guard has been extracted to `validate-entry.ts`
 10	 * for direct testability; it is imported here and re-used at the filter call site.
 11	 *
 12	 * Exports beyond `getQueue()`:
 13	 *   - `readQueueFile` — used by `checkNoConflict` in `orchestrator-manager.ts`.
 14	 *   - `isProcessAlive` — used by queue-mutation functions in `orchestrator-manager.ts`.
 15	 *   - `getProjectLedgerStatus` — used by `killQueueEntry`/`dismissQueueEntry`
 16	 *     in `orchestrator-manager.ts`.
 17	 */
 18	
 19	import { readFile } from 'node:fs/promises';
 20	import { join } from 'node:path';
 21	
 22	import { QUEUE_FILENAME, type RawQueueEntry, type QueueEntry } from './types.js';
 23	import { isRawQueueEntry } from './validate-entry.js';
 24	import { resolveProgress } from './resolve-progress.js';
 25	import { computeEffectiveStatus } from './compute-effective-status.js';
 26	
 27	// ---------------------------------------------------------------------------
 28	// PID alive check
 29	// ---------------------------------------------------------------------------
 30	
 31	/**
 32	 * Returns `true` if the process with `pid` exists on this machine.
 33	 *
 34	 * Uses `process.kill(pid, 0)` which is a zero-signal check — it only
 35	 * verifies the process exists and does not actually deliver any signal.
 36	 *
 37	 * Exported for use by queue-mutation functions in `orchestrator-manager.ts`.
 38	 */
 39	export function isProcessAlive(pid: number): boolean {
 40	  try {
 41	    process.kill(pid, 0);
 42	    return true;
 43	  } catch {
 44	    return false;
 45	  }
 46	}
 47	
 48	// ---------------------------------------------------------------------------
 49	// Queue file reader
 50	// ---------------------------------------------------------------------------
 51	
 52	/**
 53	 * Reads and parses `<logsDir>/.run-queue.json`.
 54	 * Returns `[]` on any I/O or parse error — fail-safe.
 55	 * Never writes to the queue file.
 56	 *
 57	 * Exported for use by `checkNoConflict` in `orchestrator-manager.ts`.
 58	 */
 59	export async function readQueueFile(logsDir: string): Promise<RawQueueEntry[]> {
 60	  const queuePath = join(logsDir, QUEUE_FILENAME);
 61	  let raw: string;
 62	  try {
 63	    raw = await readFile(queuePath, 'utf-8');
 64	  } catch {
 65	    return [];
 66	  }
 67	  try {
 68	    const data: unknown = JSON.parse(raw);
 69	    if (!Array.isArray(data)) return [];
 70	    return data.filter(isRawQueueEntry);
 71	  } catch {
 72	    return [];
 73	  }
 74	}
 75	
 76	// ---------------------------------------------------------------------------
 77	// Project ledger check
 78	// ---------------------------------------------------------------------------
 79	
 80	/**
 81	 * Returns whether the project identified by `slug` has a ledger entry and
 82	 * whether synthesis has been generated for it.
 83	 *
 84	 * Fail-safe: any I/O or parse error returns `{ exists: false, synthesisGenerated: false }`.
 85	 *
 86	 * Exported for use by `killQueueEntry`/`dismissQueueEntry` in `orchestrator-manager.ts`.
 87	 *
 88	 * @param ledgerRoot - Absolute path to the ledger root directory.
 89	 * @param slug       - Project slug (e.g. `2026-05-05-my-feature`).
 90	 * @returns An object with two fields:
 91	 *   - `exists` — `true` when `<ledgerRoot>/<slug>/project-ledger.json` is present and
 92	 *     readable; `false` on any I/O error or when the file does not exist.
 93	 *   - `synthesisGenerated` — `true` when the ledger's `synthesis_generated` field equals
 94	 *     `true`; `false` when the file is absent, unreadable, or the field is falsy.
 95	 */
 96	export async function getProjectLedgerStatus(
 97	  ledgerRoot: string,
 98	  slug: string,
 99	): Promise<{ exists: boolean; synthesisGenerated: boolean }> {
100	  const projectLedgerPath = join(ledgerRoot, slug, 'project-ledger.json');

101	  let raw: string;
102	  try {
103	    raw = await readFile(projectLedgerPath, 'utf-8');
104	  } catch {
105	    return { exists: false, synthesisGenerated: false };
106	  }
107	  try {
108	    const data = JSON.parse(raw) as Record<string, unknown>;
109	    return {
110	      exists: true,
111	      synthesisGenerated: data['synthesis_generated'] === true,
112	    };
113	  } catch {
114	    return { exists: true, synthesisGenerated: false };
115	  }
116	}
117	
118	// ---------------------------------------------------------------------------
119	// Public API
120	// ---------------------------------------------------------------------------
121	
122	/**
123	 * Reads the shared orchestrator run queue and returns all active entries
124	 * enriched with computed lifecycle state and JSONL progress summaries.
125	 *
126	 * Entries for completed projects (`synthesis_generated === true`) are
127	 * automatically excluded from the result.
128	 *
129	 * This function is read-only: it never writes to the queue file or any
130	 * other file on disk.
131	 *
132	 * @param params.logsDir    - Absolute path to `orchestrator/logs/`.
133	 * @param params.ledgerRoot - Absolute path to the central ledger root.
134	 * @returns Enriched queue entries, excluding completed runs.
135	 */
136	export async function getQueue(params: {
137	  logsDir: string;
138	  ledgerRoot: string;
139	}): Promise<QueueEntry[]> {
140	  const { logsDir, ledgerRoot } = params;
141	
142	  const rawEntries = await readQueueFile(logsDir);
143	  if (rawEntries.length === 0) return [];
144	
145	  const enriched = await Promise.all(
146	    rawEntries.map(async (entry) => {
147	      const [projectStatus, progressResult] = await Promise.all([
148	        getProjectLedgerStatus(ledgerRoot, entry.expectedSlug),
149	        resolveProgress(logsDir, entry.expectedSlug),
150	      ]);
151	
152	      const { exists: projectExists, synthesisGenerated } = projectStatus;
153	      const alive = isProcessAlive(entry.pid);
154	
155	      // Compute effective status per AC-2 through AC-5.
156	      const effectiveStatus = computeEffectiveStatus(alive, projectExists, progressResult.hasStageActivity);
157	
158	      // AC-6: exclude entries whose project has completed synthesis.
159	      if (effectiveStatus === 'started' && synthesisGenerated) {
160	        return null;
161	      }
162	
163	      const result: QueueEntry = {
164	        ...entry,
165	        effectiveStatus,
166	        progress:      progressResult.summary,
167	        lastAction:    progressResult.lastAction,
168	        logFilename:   progressResult.logFilename,
169	        projectExists,
170	      };
171	      return result;
172	    }),
173	  );
174	
175	  return enriched.filter((e): e is QueueEntry => e !== null);
176	}

